// Armies, as data. A "family" holds what stays the same across a nation's wars
// (rank titles, names, awards, how service numbers and call signs look, the
// classification stamp); an army entry holds what one army in one era carried
// (weapons, radios, vehicles, fire support, medicine, slang). armyById() merges
// the two. Adding an army to an era is adding one entry here and listing its
// id in the theatre in eras.js.

const R = s => Object.fromEntries(s.split(';').map(x => x.trim()).filter(Boolean).map(x => { const [k, v] = x.split(':'); const [full, abbr] = v.split('|'); return [k.trim(), [full.trim(), (abbr || full).trim()]]; }));

