/** Merge a family with an army entry. */
export function armyById(id) {
  const a = ARMIES[id];
  if (!a) return null;
  const fam = FAMILIES[a.family] || FAMILIES.us_army;
  const ranks = a.modern && fam.modernRanks ? fam.modernRanks : fam.ranks;
  return { id, ...fam, ...a, ranks, names: a.names || fam.names, adjective: a.adjective || fam.adjective, echelonRank: { ...ECHELON_RANK, ...(fam.echelonRank || {}) }, roleRank: { ...ROLE_RANK, ...(fam.roleRank || {}) } };
}

/** [full title, abbreviation] for a rank key in an army. */
export function rankTitle(army, key) {
  const r = army?.ranks?.[key];
  if (r) return r;
  return ['Soldier', 'Sdr'];
}

/** The player's rank at an echelon. platoonSgt picks the senior NCO path at platoon level. */
export function playerRank(army, echelonId, { platoonSgt = false, branch = null } = {}) {
  const key = echelonId === 'platoon' && platoonSgt ? army.echelonRank.platoonSgt : army.echelonRank[echelonId];
  const [full, abbr] = rankTitle(army, key);
  if (echelonId === 'corps' && army.branchGeneral?.[branch]) return { key, full: army.branchGeneral[branch], abbr: 'Gen.' };
  return { key, full, abbr };
}

export function roleRank(army, role, rnd = Math.random) {
  const k = army.roleRank[role];
  const key = Array.isArray(k) ? k[Math.floor(rnd() * k.length)] : k;
  const [full, abbr] = rankTitle(army, key);
  return { key, full, abbr };
}

/** Awards an army hands out, filtered by year. */
export function awardsFor(army, year) {
  return (army.awards || []).filter(a => !a.fromYear || year >= a.fromYear);
}
